    def fmt(g, er, ec):
        return f'{len(g)} {len(g[0])}\n' + '\n'.join(g) + f'\n{er} {ec}'

    def border(r, c):
        return [(x, y) for x in range(r) for y in range(c) if x in (0, r - 1) or y in (0, c - 1)]

    def rand_grid(r, c, p):
        g = [['+' if rng.random() < p else '.' for _ in range(c)] for _ in range(r)]
        er, ec = rng.choice(border(r, c))
        g[er][ec] = '.'
        return fmt([''.join(row) for row in g], er, ec)

    tests = [fmt(['.'], 0, 0), fmt(['..'], 0, 0), fmt(['.+.'], 0, 0), fmt(['...'], 0, 1 - 1),
             fmt(['++.++', '.....', '+++++'], 1, 0), fmt(['+++', '.+.', '+++'], 1, 0),
             fmt(['+.+', '+.+', '+.+'], 0, 1), fmt(['++++', '+..+', '+..+', '+++.'], 3, 3)]
