    # snake corridor through the interior; entrance on the left border, exit on the right border at the end
    def snake(r, c, open_end):
        g = [['+'] * c for _ in range(r)]
        for i in range(1, r - 1, 2):
            for j in range(1, c - 1):
                g[i][j] = '.'
            if i + 2 <= r - 2:
                j = c - 2 if (i // 2) % 2 == 0 else 1
                g[i + 1][j] = '.'
        g[1][0] = '.'
        last = r - 2 if (r - 2) % 2 == 1 else r - 3
        if open_end:
            g[last][c - 1 if (last // 2) % 2 == 0 else 0] = '.'
        return fmt([''.join(row) for row in g], 1, 0)
    tests.append(snake(499, 499, True))
    tests.append(snake(499, 499, False))
    tests.append(fmt(['.' * 500] * 500, 250, 0))
    return tests

